import React, { useEffect, useState } from "react";
import { Line } from "react-chartjs-2";

import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

const CpuStatsGraph = () => {
  const [data, setData] = useState([]);

  useEffect(() => {
    // Replace '/api/cpu-usage' with the actual API endpoint for fetching CPU usage data
    fetch('/api/cpu-usage')
      .then((response) => response.json())
      .then((fetchedData) => {
        setData(fetchedData); // Set data from API in the component state
      })
      .catch((error) => console.error("Error fetching CPU usage data:", error));
  }, []); // Empty dependency array means this runs only once, when the component mounts

  const cpuUsage = {
    labels: data.map((point) => new Date(point.time).toLocaleTimeString()), // Adjust based on your time format
    datasets: [
      {
        label: "CPU Usage",
        data: data.map((point) => point.cpu_usage), // Adjust based on your data structure
        fill: false,
        borderColor: "rgb(75, 192, 192)",
        tension: 0.1,
      },
    ],
  };

  const cpuTemp = {
    labels: data.map((point) => new Date(point.time).toLocaleTimeString()), // Adjust based on your time format
    datasets: [
      {
        label: "CPU Temperature",
        data: data.map((point) => point.cpu_temp), // Adjust based on your data structure
        fill: false,
        borderColor: "rgb(255, 99, 132)",
        tension: 0.1,
      },
    ],
  };

  const memUsage = {
    labels: data.map((point) => new Date(point.time).toLocaleTimeString()), // Adjust based on your time format
    datasets: [
      {
        label: "Memory Usage",
        data: data.map((point) => point.cpu_temp), // Adjust based on your data structure
        fill: false,
        borderColor: "rgb(255, 99, 132)",
        tension: 0.1,
      },
    ],
  };

  return (
    <div>
      <h2>CPU Stats</h2>
      <Line data={cpuUsage} />
      <Line data={cpuTemp} />
      <Line data={memUsage} />
    </div>
  );
};

export default CpuStatsGraph;
